1	import SidebarLayout from "@/components/SidebarLayout";
2	import { useQuery } from "@tanstack/react-query";
3	import { useAuth } from "@/hooks/useAuth";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
6	import { Badge } from "@/components/ui/badge";
7	import { Separator } from "@/components/ui/separator";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { Mail, Calendar, Briefcase, FileText, Zap, Crown } from "lucide-react";
10	import { toast } from "sonner";
11	import ChangePasswordCard from "@/components/settings/ChangePasswordCard";
12	
13	function getInitials(email?: string | null): string {
14	  if (!email) return "?";
15	  const name = email.split("@")[0];
16	  const parts = name.split(/[._-]/);
17	  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
18	  return name[0]?.toUpperCase() || "?";
19	}
20	
21	function getUserName(email?: string | null): string {
22	  if (!email) return "User";
23	  return email.split("@")[0].replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
24	}
25	
26	const Profile = () => {
27	  const { user, profile } = useAuth();
28	  const plan = profile?.plan ?? "free";
29	  const isPaid = plan !== "free";
30	
31	  // Fetch usage stats (cached via React Query — no refetch on navigation)
32	  const { data: stats } = useQuery({
33	    queryKey: ["profileStats", user?.id],
34	    queryFn: async () => {
35	      const [jobsRes, usageRes] = await Promise.all([
36	        supabase.from("jobs").select("id, resumes(count)").eq("user_id", user!.id),
37	        supabase.from("usage_logs").select("credits_used").eq("user_id", user!.id),
38	      ]);
39	      const jobs = jobsRes.data ?? [];
40	      const totalJobs = jobs.length;
41	      const totalResumes = jobs.reduce((sum: number, j: any) => sum + (j.resumes?.[0]?.count ?? 0), 0);
42	      const creditsUsed = (usageRes.data ?? []).reduce((sum: number, u: any) => sum + (u.credits_used ?? 0), 0);
43	      return { totalJobs, totalResumes, creditsUsed };
44	    },
45	    enabled: !!user,
46	    staleTime: 5 * 60 * 1000,
47	  });
48	
49	  // Credits
50	  const sub = profile?.subscription_credits ?? 0;
51	  const top = profile?.topup_credits ?? 0;
52	  const bonus = profile?.bonus_credits ?? 0;
53	  const split = sub + top + bonus;
54	  const totalCredits = split > 0 ? split : (profile?.credits ?? 0);
55	
56	  return (
57	    <SidebarLayout>
58	      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
59	        <h1 className="text-2xl font-bold text-foreground mb-6">Profile</h1>
60	        <div className="space-y-6">
61	          {/* Account card */}
62	          <Card className="border border-border/60 shadow-sm">
63	            <CardContent className="p-6">
64	              <div className="flex items-center gap-4">
65	                <div className="h-14 w-14 rounded-full bg-primary text-primary-foreground text-lg font-bold flex items-center justify-center shrink-0">
66	                  {getInitials(user?.email)}
67	                </div>
68	                <div className="min-w-0 flex-1">
69	                  <h2 className="text-lg font-semibold text-foreground truncate">{getUserName(user?.email)}</h2>
70	                  <p className="text-sm text-muted-foreground truncate">{user?.email}</p>
71	                  <div className="flex items-center gap-2 mt-1.5">
72	                    <Badge variant={isPaid ? "default" : "secondary"} className="text-xs capitalize gap-1">
73	                      {isPaid && <Crown className="h-3 w-3" />}
74	                      {plan} plan
75	                    </Badge>
76	                    <Badge variant="outline" className="text-xs tabular-nums">{totalCredits} credits</Badge>
77	                  </div>
78	                </div>
79	              </div>
80	
81	              <Separator className="my-5" />
82	
83	              <div className="grid grid-cols-2 gap-4 text-sm">
84	                <div className="flex items-center gap-2.5">
85	                  <Mail className="h-4 w-4 text-muted-foreground" />
86	                  <div>
87	                    <p className="text-xs text-muted-foreground">Email</p>
88	                    <p className="text-foreground truncate">{user?.email}</p>
89	                  </div>
90	                </div>
91	                <div className="flex items-center gap-2.5">
92	                  <Calendar className="h-4 w-4 text-muted-foreground" />
93	                  <div>
94	                    <p className="text-xs text-muted-foreground">Member since</p>
95	                    <p className="text-foreground">{user?.created_at ? new Date(user.created_at).toLocaleDateString("en-US", { month: "long", year: "numeric" }) : "—"}</p>
96	                  </div>
97	                </div>
98	                <div className="flex items-center gap-2.5">
99	                  <Zap className="h-4 w-4 text-muted-foreground" />
100	                  <div>
101	                    <p className="text-xs text-muted-foreground">Subscription</p>
102	                    <p className="text-foreground">{profile?.subscription_ends_at ? `Until ${new Date(profile.subscription_ends_at).toLocaleDateString("en-US", { month: "short", year: "numeric" })}` : "None"}</p>
103	                  </div>
104	                </div>
105	              </div>
106	            </CardContent>
107	          </Card>
108	
109	          {/* Change password */}
110	          <ChangePasswordCard />
111	
112	          {/* Usage stats */}
113	          <Card className="border border-border/60 shadow-sm">
114	            <CardHeader className="pb-3 px-6 pt-5">
115	              <CardTitle className="text-sm font-semibold">Activity</CardTitle>
116	            </CardHeader>
117	            <CardContent className="px-6 pb-5">
118	              {!stats ? (
119	                <div className="grid grid-cols-3 gap-4">
120	                  {[0, 1, 2].map((i) => (
121	                    <div key={i} className="space-y-1.5">
122	                      <Skeleton className="h-7 w-12" />
123	                      <Skeleton className="h-3 w-20" />
124	                    </div>
125	                  ))}
126	                </div>
127	              ) : (
128	                <div className="grid grid-cols-3 gap-4">
129	                  <div>
130	                    <div className="flex items-center gap-2">
131	                      <Briefcase className="h-4 w-4 text-muted-foreground" />
132	                      <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalJobs}</span>
133	                    </div>
134	                    <p className="text-xs text-muted-foreground mt-0.5">Jobs created</p>
135	                  </div>
136	                  <div>
137	                    <div className="flex items-center gap-2">
138	                      <FileText className="h-4 w-4 text-muted-foreground" />
139	                      <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalResumes}</span>
140	                    </div>
141	                    <p className="text-xs text-muted-foreground mt-0.5">Resumes ranked</p>
142	                  </div>
143	                  <div>
144	                    <div className="flex items-center gap-2">
145	                      <Zap className="h-4 w-4 text-muted-foreground" />
146	                      <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.creditsUsed}</span>
147	                    </div>
148	                    <p className="text-xs text-muted-foreground mt-0.5">Credits used</p>
149	                  </div>
150	                </div>
151	              )}
152	            </CardContent>
153	          </Card>
154	
155	        </div>
156	      </main>
157	    </SidebarLayout>
158	  );
159	};
160	
161	export default Profile;
162	
