82	            className={passwordsMismatch ? "border-destructive focus-visible:ring-destructive" : passwordsMatch ? "border-primary/50 focus-visible:ring-primary" : ""}
83	          />
84	          {passwordsMismatch && (
85	            <p className="text-xs text-destructive">Passwords don't match.</p>
86	          )}
87	          {passwordsMatch && (
88	            <p className="text-xs text-primary">Passwords match ✓</p>
